/* Group G06 mastery bank: Departments, employment types and communication; Recruiting and training staff; Motivating staff. Original questions, not copied from past papers. */
(function () {
  'use strict';
  var B = window.MASTERY_BANKS = window.MASTERY_BANKS || {};
  var R = window.Mastery;   // R.roundDp(x, dp), R.roundSf(x, n): correct half-up rounding

  function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
  function rint(lo, hi) { return lo + Math.floor(Math.random() * (hi - lo + 1)); }
  function shuffled(a) { a = a.slice(); for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(Math.random() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function commas(n) { var s = String(n).split('.'); s[0] = s[0].replace(/\B(?=(\d{3})+(?!\d))/g, ','); return s.join('.'); }
  function money(x) { var r = R.roundDp(x, 2); return Number.isInteger(r) ? commas(r) : commas(r.toFixed(2)); }
  function mc(skill, q, options, why, family) { var o = { skill: skill, kind: 'mcq', q: q, options: options, answer: 0, why: why }; if (family) o.family = family; return o; }
  function mu(skill, q, options, answers, why, family) { var o = { skill: skill, kind: 'multi', q: q, options: options, answers: answers, why: why }; if (family) o.family = family; return o; }

  var DEPTS = ['Human resources', 'Finance', 'Marketing', 'Production'];

  /* ------------------------------------------------------------------ */
  B['BUS-S2-34'] = { title: 'Functional areas and the human resources role', items: [
    mc('match-task', "Ravel Furniture makes wooden tables. Which department would pay the monthly salaries of its carpenters?",
      ['Finance', 'Human resources', 'Production', 'Marketing'],
      "Paying wages and salaries is a finance task because it involves money. Human resources plans how many staff are needed, but finance makes the payments."),
    mc('match-task', "Which department at a bicycle factory would check finished frames for faults before they are packed?",
      ['Production', 'Marketing', 'Finance', 'Human resources'],
      "Quality control is part of production, the department that makes the product and makes sure it meets the required standard."),
    mc('match-task', "Zesta Drinks wants to find out which new juice flavour young customers prefer. Which department would organise this research?",
      ['Marketing', 'Production', 'Finance', 'Human resources'],
      "Market research is a marketing task. Marketing finds out what customers want before the business decides what to make and sell."),
    mc('match-task', "A courier firm needs to work out how many extra drivers it will need next year. Which department would draw up this workforce plan?",
      ['Human resources', 'Finance', 'Production', 'Marketing'],
      "Workforce planning means working out how many staff, with which skills, the business will need. This is a human resources task."),
    mc('match-task', "Which department would prepare a cash-flow forecast for the next six months?",
      ['Finance', 'Marketing', 'Human resources', 'Production'],
      "Cash-flow forecasting predicts money coming in and going out, so it belongs to finance, along with budgets and accounts."),
    mc('match-task', "A bakery is running low on flour and sugar. Which department is responsible for stock control of these ingredients?",
      ['Production', 'Finance', 'Marketing', 'Human resources'],
      "Stock control is a production task: production makes sure there are enough materials to keep making the product without holding too much."),
    mc('match-task', "An employee at a call centre makes a formal complaint that her manager treats her unfairly. Which department deals with this grievance?",
      ['Human resources', 'Marketing', 'Finance', 'Production'],
      "Grievance and disciplinary procedures are about people at work, so they are handled by human resources."),
    mc('match-task', "Which department would decide the price of a new range of sun hats?",
      ['Marketing', 'Finance', 'Production', 'Human resources'],
      "Pricing is one of the marketing tasks in the specification, together with advertising, sales promotion and distribution. Finance supplies cost figures, but setting the selling price is a marketing decision."),
    mc('odd-one-out', "Which of these tasks is <b>not</b> normally carried out by the human resources department?",
      ['Sending invoices to customers', 'Organising staff training', 'Recruiting new employees', 'Checking health and safety at work'],
      "Sending invoices is about money owed to the business, so it is a finance task. The other three are about people, which is the role of human resources."),
    mc('odd-one-out', "Which of these tasks is <b>not</b> a marketing task?",
      ['Quality control of products', 'Planning a sales promotion', 'Deciding how to distribute goods', 'Handling public relations'],
      "Quality control belongs to production. Sales promotion, distribution and public relations are all marketing tasks because they deal with customers."),
    mc('odd-one-out', "Which of these tasks is <b>not</b> a production task?",
      ['Setting the annual budget', 'Manufacturing the product', 'Designing a new product', 'Controlling stock levels'],
      "Budgets are planned and monitored by finance. Production makes the product, designs new products and controls stock."),
    mu('odd-one-out', "Which tasks would the finance department of a clothing retailer carry out?",
      ['Paying suppliers for delivered stock', 'Keeping the accounts', 'Interviewing shop assistants', 'Designing window displays', 'Testing fabric quality'],
      [0, 1],
      "Finance deals with money: paying suppliers and keeping accounts. Interviewing is human resources, displays are marketing and testing fabric is production quality control."),
    mu('odd-one-out', "Which tasks are part of the human resources role?",
      ['Looking after staff welfare', 'Running disciplinary procedures', 'Arranging employee training', 'Deciding the selling price', 'Ordering raw materials'],
      [0, 1, 2],
      "Staff welfare, discipline and training are all about people, so they belong to human resources. Pricing is marketing and ordering materials is production stock control."),
    mc('hr-purpose', "Why does a business need a human resources function?",
      ['To make sure it has enough suitable, trained staff and follows employment law',
       'To make sure every product is made to the right quality standard before it is sold to customers',
       'To make sure customers know about the products and their prices',
       'To make sure suppliers and staff are paid the correct amounts on time'],
      "Human resources manages the people in the business: having the right number of skilled, trained staff and keeping within employment law. The other options describe production, marketing and finance."),
    mc('hr-purpose', "A small hotel has grown from 6 to 60 staff and decides to set up a human resources department. Which is the most likely reason?",
      ['There are now too many recruitment, training and staff issues for the owner to handle alone',
       'The hotel now needs someone to set room prices, plan promotions and run its advertising campaigns',
       'The hotel now needs someone to prepare its accounts for tax',
       'The hotel now needs someone to check the quality of the rooms'],
      "With 60 staff there is much more hiring, training, welfare and discipline to manage, which is the work of human resources. The other reasons belong to marketing, finance and production."),
    mc('explain-chain', "A student is asked to explain one responsibility of human resources. Which answer is the best developed?",
      ['HR trains warehouse staff to lift loads safely, so fewer are injured, which means less working time is lost to sick leave.',
       'HR is responsible for recruitment, selection, training, health and safety, staff welfare, discipline, grievances and dismissal.',
       'HR is the department responsible for all of the people who work in the business, from the newest trainee up to the senior managers.',
       'HR is responsible for health and safety, which is a very important part of running any business.'],
      "The best answer names one responsibility (health and safety training) and then adds two linked steps: staff work safely, so fewer injuries and less lost time. Listing several tasks or defining HR earns little credit."),
    mc('explain-chain', "Complete the chain: \"HR recruits staff who have the right skills for each job, so &hellip;\". Which next step develops the point best?",
      ['new staff need less training and can work well sooner, raising productivity',
       'the finance department can pay the new staff their wages and salaries at the end of each month',
       'the business can design a new product range for its customers',
       'the marketing department can launch a new advertising campaign'],
      "The next step must follow from hiring skilled staff: they need less training and are productive sooner. The other steps are about other departments and do not follow from the recruitment point."),
    mc('applied-context', "Kaveri Tiles makes ceramic floor tiles in a large factory. Which is a production task in the context of Kaveri Tiles?",
      ['Testing a sample of each batch of tiles for cracks', 'Paying the kiln operators their weekly wages', 'Advertising the new tile range in home and garden magazines', 'Recruiting a new factory supervisor'],
      "Testing tiles for cracks is quality control, which is a production task. Paying wages is finance, advertising is marketing and recruiting is human resources."),
    mc('applied-context', "Lumo Lights sells desk lamps online. A customer emails to say her lamp arrived late and she wants to know where it is. Which department deals with this?",
      ['Marketing, because it is customer service', 'Production, because it made the lamp', 'Finance, because the customer has paid', 'Human resources, because staff are involved'],
      "Customer service and distribution are listed under marketing. Marketing looks after customers, including dealing with delivery questions."),
    mc('applied-context', "A student says: \"At Ravi's Garage, human resources pays the mechanics their wages.\" What is wrong with this statement?",
      ['Paying wages is a finance task; HR plans staffing and recruits mechanics',
       'Paying wages is a production task because mechanics repair the cars',
       'Paying wages is a marketing task because wages affect the prices charged',
       'Nothing is wrong, because HR is responsible for all staff matters'],
      "Paying wages and salaries involves money, so it is done by finance. HR decides how many mechanics are needed and recruits and trains them."),
    mc('applied-context', "Why do the departments of a business need to work together?",
      ['They rely on each other, for example production uses marketing sales forecasts to plan output',
       'Working together means each department can do every task itself without needing help from the others',
       'Working together means the business no longer needs a finance department',
       'Working together means the business can stop doing any market research'],
      "Departments depend on each other. For example, marketing predicts sales, production plans output to match and finance budgets for the costs."),
    { skill: 'match-task', gen: function () {
      var pool = [
        ['arranging induction for new warehouse staff', 0], ['handling a complaint from an employee about unfair treatment', 0], ['planning how many nurses a clinic will need next year', 0],
        ['paying invoices from a packaging supplier', 1], ['preparing next year\'s budget for each branch', 1], ['recording all sales and costs in the accounts', 1],
        ['running a social media advertising campaign', 2], ['carrying out a survey of customer opinions', 2], ['deciding the packaging design for a new snack', 2],
        ['checking a sample of finished phones for faults', 3], ['ordering enough raw materials to meet next week\'s output', 3], ['operating the machines on the assembly line', 3]
      ];
      var t = pick(pool), biz = pick(['Orchid Foods', 'Tallis Electronics', 'Brightwater Clinics', 'Kodo Packaging', 'Sable Outdoor Wear']);
      var why = ["People tasks such as recruitment, induction, staff planning and grievances belong to human resources.",
        "Money tasks such as paying suppliers, budgets and accounts belong to finance.",
        "Customer tasks such as advertising, market research and packaging belong to marketing.",
        "Making the product, quality control and stock control belong to production."][t[1]];
      return { kind: 'mcq', q: 'At ' + biz + ', which department would be responsible for ' + t[0] + '?', options: DEPTS.slice(), answer: t[1], why: why };
    } }
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-01'] = { title: 'Communication: methods, barriers and why it matters', items: [
    mc('internal-external', "Which of these is external communication for a car hire company?",
      ['Emailing a supplier to change the date of a tyre delivery', 'A staff briefing about the new booking system', 'A manager texting one of the company drivers about a shift change', 'A notice in the staff room about holiday dates'],
      "External communication is with people outside the business, such as suppliers. The other three messages stay inside the business, so they are internal."),
    mc('internal-external', "Which of these is internal communication for a supermarket?",
      ['A memo from the store manager to all checkout staff', 'A leaflet posted to local homes about weekly offers', 'A phone call to the bank about a loan', 'A letter to a farmer ordering more potatoes'],
      "Internal communication happens between people inside the business, such as a manager and staff. Customers, the bank and suppliers are outside the business."),
    mu('internal-external', "A hotel sends several messages. Which of them are external communication?",
      ['A newsletter emailed to past guests', 'A complaint reply sent to a guest', 'A rota emailed to cleaning staff', 'A training meeting for receptionists', 'A team chat message between chefs'],
      [0, 1],
      "Guests are outside the business, so messages to them are external. Rotas, training meetings and chats between staff are internal."),
    { skill: 'internal-external', gen: function () {
      var ext = ['sending a customer a reminder about an unpaid bill', 'asking a supplier for a quote for new shelving', 'replying to a journalist about a product recall', 'posting a special offer to customers on social media', 'writing to the bank about extending an overdraft'];
      var int = ['a weekly team meeting in the warehouse', 'an email from the finance manager to all branch managers', 'a poster in the staff canteen about fire drills', 'a video call between two departments about a project', 'a supervisor giving instructions to new trainees', 'the staff newsletter sent to every employee'];
      var biz = pick(['a furniture retailer', 'a cleaning company', 'a sports clothing brand', 'a travel agency', 'a printing firm']);
      var opts = [pick(ext)].concat(shuffled(int).slice(0, 3));
      return { kind: 'mcq', q: 'Which of these is an example of external communication for ' + biz + '?', options: opts, answer: 0,
        why: 'External communication is with people outside the business, such as customers, suppliers, the media or the bank. "' + opts[0] + '" reaches an outsider; the other three stay inside the business.' };
    } },
    mc('methods', "A manager must give the same detailed instructions to 40 staff in three branches today and keep a written record. Which method suits this best?",
      ['Email', 'A face-to-face meeting', 'A phone call to each person', 'A noticeboard in one branch'],
      "Email reaches many people in different places quickly and leaves a written record. A meeting cannot gather three branches today, phone calls take too long and leave no record, and one noticeboard misses two branches."),
    mc('methods', "A manager needs to discuss a sensitive problem with one employee and let him ask questions. Which method suits this best?",
      ['A private face-to-face meeting', 'A notice on the staff board', 'A letter posted to his home address', 'A group email to the team'],
      "A face-to-face meeting is private and two-way, so the employee can ask questions and the manager can check he understands. The other methods are one-way or not private."),
    mc('methods', "What is a limitation of using a noticeboard to tell staff about a change in shift times?",
      ['Some staff may not read it and there is no way to check they understood', 'It is far more expensive than holding a meeting with every member of staff', 'It cannot be used for any kind of internal communication', 'It is only suitable for communicating with customers'],
      "A noticeboard is cheap, but it is one-way: the business cannot be sure staff have read it, and staff cannot easily ask questions."),
    mc('methods', "Arcadia Engineering has offices in four countries. What is the main benefit of using video calls for its weekly management meeting?",
      ['Managers can discuss issues face to face without the cost and time of travel', 'Video calls automatically leave a printed record of every decision the managers make', 'Video calls remove all language barriers between managers', 'Video calls mean managers never need to communicate in writing'],
      "Video calls let managers see and hear each other and give instant feedback, while saving travel time and cost. They do not remove language barriers or automatically create a written record."),
    mc('methods', "Which is a limitation of using email for internal communication?",
      ['Staff receive so many emails that important messages may be missed', 'Email cannot be sent to more than one employee at a time, so it is slow for big teams', 'Email leaves no record of what was said', 'Email can only be used by managers'],
      "Email can be sent to many people and leaves a record, but too many emails cause overload, so key messages may be ignored or read late."),
    mc('barriers', "A software engineer explains a fault to the sales team using technical terms they do not understand. Which barrier to communication is this?",
      ['Jargon', 'A long chain of command', 'Background noise', 'Poor technology'],
      "Jargon is specialist language that the receiver does not understand. The message is sent, but it is not understood, so communication fails."),
    mc('barriers', "In a large bank, a message from the chief executive passes through five levels of management before it reaches counter staff. Why might this be a barrier?",
      ['The message may be changed or delayed as it passes through each level', 'Counter staff are not allowed to receive messages from senior managers', 'The message will always be sent in a language staff cannot read', 'Each level of management charges a fee for passing the message on'],
      "A long chain of command means the message goes through many people. Each step can delay it or distort it, so the receiver may get a different message from the one that was sent."),
    mc('barriers', "Staff in a busy metal workshop often mishear spoken instructions from their supervisor. Which barrier is most likely to be the cause?",
      ['Noise from the machines', 'Jargon in written reports', 'A long chain of command', 'Language differences'],
      "In a noisy workshop the spoken message is not heard clearly. This is a physical barrier: the receiver cannot take in the message."),
    mc('barriers', "A garden centre in Spain buys plants from a grower in the Netherlands. Orders are often wrong because neither side speaks the other's language well. How could this barrier best be removed?",
      ['Send orders in writing in a shared language and ask the grower to confirm them', 'Increase the number of orders sent each month', 'Use more technical gardening terms in each order so the grower knows exactly what is meant', 'Stop asking the grower for any feedback'],
      "Using a shared written language and asking for confirmation (feedback) checks that the message has been understood. More technical terms or fewer checks would make the problem worse."),
    mu('removing-barriers', "Which actions would help remove barriers to communication?",
      ['Using simple language instead of jargon', 'Asking receivers to confirm what they understood', 'Shortening the chain of command', 'Adding more levels of management', 'Sending every message by noticeboard only'],
      [0, 1, 2],
      "Plain language, feedback and a shorter chain of command all help the message arrive and be understood. More management levels and a single one-way method make barriers worse."),
    mc('removing-barriers', "Which of these would <b>not</b> help to remove a barrier to communication?",
      ['Passing every message through more managers to check it', 'Choosing a method that suits the message and the receiver', 'Checking for feedback after giving instructions', 'Avoiding technical terms with non-specialist staff'],
      "Passing a message through more managers lengthens the chain of command, so it is more likely to be delayed or distorted. The other three actions improve understanding."),
    mc('effects-chain', "Asked how poor communication can affect a business, which student answer is developed the furthest?",
      ['Staff misunderstand which orders are urgent, so urgent parcels go out late, so customers complain and may switch to rivals.',
       'Ineffective communication causes mistakes, low motivation, wasted time, higher costs, missed deadlines and unhappy customers.',
       'Ineffective communication is when a message from the sender is not received, or is received but not understood, by the receiver.',
       'Ineffective communication is a problem that most businesses will face at some point.'],
      "The best answer names one impact and develops it in two linked steps: wrong priorities, late deliveries, then lost customers. A list or a definition earns only limited credit."),
    mc('effects-chain', "Find the missing step. \"Packing instructions at an online shop are unclear &rarr; ________ &rarr; customers receive the wrong items and ask for refunds.\"",
      ['Staff make mistakes when packing orders', 'The shop opens a second, larger warehouse', 'The shop lowers its prices', 'Staff ask for a pay rise'],
      "Unclear instructions lead to packing errors, and those errors lead to wrong items and refunds. The other steps do not link the cause to the effect."),
    mu('effects-chain', "A student writes: \"Improving communication with employees means they understand exactly what to do.\" Which two steps develop this point into a chain?",
      ['so fewer mistakes are made', 'which increases productivity and lowers costs', 'so the business must hire more managers', 'which means employees need more meetings', 'so the business will pay less tax'],
      [0, 1],
      "Clear understanding leads to fewer mistakes, and fewer mistakes raise productivity and cut costs. The other steps do not follow logically from the point."),
    mc('effects-chain', "Staff at a printing firm are not told about a change to the bonus scheme until it appears on their payslips. What is the most likely effect?",
      ['Staff feel undervalued and become demotivated, so productivity may fall', 'Staff become more motivated because the change came as a pleasant surprise to them', 'Customers will immediately pay their bills more quickly', 'The firm will be able to cut its advertising budget'],
      "When staff are not informed about changes that affect them, they may feel ignored. Demotivated staff tend to work less hard and may leave."),
    mc('effects-chain', "Why should a dental clinic communicate clearly with its patients about appointment times?",
      ['Fewer patients miss appointments, so dentists\' time is not wasted and revenue is protected', 'Clear communication with patients means the clinic no longer needs to hold any staff meetings', 'Clear communication means the clinic can pay its suppliers later', 'Patients will no longer need any treatment from the dentists'],
      "This is external communication with customers. Clear reminders reduce missed appointments, so the clinic uses its dentists' time fully and keeps its income."),
    mc('justify-method', "Tamarind Kitchen, a café with 6 staff in one building, is changing its menu. The owner wants staff to understand the new dishes and ask questions. Which conclusion is best justified?",
      ['A short staff meeting: staff can ask questions and the owner can check they understand, which a notice cannot do',
       'A notice on the staff board, because it is cheaper than a meeting and notices are always the best method for every message',
       'A letter to each employee\'s home, because letters are the quickest method',
       'An advert in the local newspaper, because it reaches the most people'],
      "A justified choice weighs both methods in the case. With only 6 staff in one place, a meeting is easy to arrange and allows two-way discussion, which a one-way notice cannot give."),
    mc('justify-method', "A student says: \"Businesses should always use email because it is the quickest method.\" What is the main weakness of this judgement?",
      ['It ignores that the best method depends on the message, such as whether discussion or privacy is needed', 'It is wrong because email is always the slowest method of communication available to a business today', 'It is wrong because email can only be used for external communication with customers and suppliers, never for staff', 'It is wrong because email always costs more than any other method'],
      "The judgement is one-sided. Speed is only one factor; cost, the need for two-way discussion, privacy and a written record also matter in each case."),
    mc('methods', "What does feedback mean in communication?",
      ['The receiver responds, showing whether the message was understood', 'The sender repeats the message more loudly so that everyone in the room hears it', 'The message is passed down the chain of command', 'The message is stored so it can be read later'],
      "Feedback is the receiver's reply to the sender. It lets the sender check that the message was received and understood correctly.")
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-06'] = { title: 'Types of employment: full-time, part-time, temporary', items: [
    mc('classify', "Two experienced accountants each work two and a half days a week, together covering one full-time accountant's role. What type of employment is this?",
      ['Job share', 'Casual work', 'Seasonal work', 'Temporary work'],
      "A job share splits one full-time job between two part-time workers who share the hours and duties."),
    mc('classify', "A ski school in the mountains employs extra instructors from December to March each year. What type of employment is this?",
      ['Seasonal', 'Job share', 'Full-time permanent', 'Casual'],
      "Seasonal staff are employed for the busy time of year only. The ski school needs instructors just during the snow season."),
    mc('classify', "Mira is hired for six months to cover a colleague's maternity leave at an insurance office. What type of employment is this?",
      ['Temporary', 'Job share', 'Part-time', 'Casual'],
      "Temporary work lasts for a fixed period, here six months to cover an absence. It says how long the job lasts, not how many hours a week."),
    mc('classify', "A wedding caterer phones waiters only when it has a booking, and pays them for the hours worked that day. What type of employment is this?",
      ['Casual', 'Job share', 'Full-time', 'Seasonal'],
      "Casual staff are called in only when they are needed. There are no fixed hours each week."),
    mc('classify', "Which statement correctly explains the difference between part-time and temporary work?",
      ['Part-time is about the hours worked each week; temporary is about how long the job lasts', 'Part-time is about how long the job lasts; temporary is about the hours worked each week', 'Part-time and temporary mean the same thing in employment', 'Part-time staff work more hours each week than temporary staff'],
      "A part-time job has fewer weekly hours than full-time but may last for years. A temporary job lasts for a fixed period and could be full-time or part-time."),
    mc('classify', "What does full-time employment normally mean?",
      ['Working the business\'s normal working week, often around 35 to 40 hours', 'Working only when the business calls the employee in', 'Working only during the busiest months of the year, such as the summer holidays', 'Sharing one job with another worker'],
      "Full-time employees work the standard number of hours set by the business each week, often about 35 to 40."),
    mc('benefits', "Asked why seasonal workers can help an employer, which student answer is developed the furthest?",
      ['Extra staff can be taken on only for busy months, so demand is met without paying their wages all year round.',
       'Seasonal employees are workers who are only employed at certain busy times of the year, such as summer or the festive season.',
       'Seasonal employees are cheaper, flexible and easy to find for most businesses.',
       'Seasonal employees are useful for many businesses in many different industries.'],
      "The best answer names a benefit (flexibility), then links it to busy periods and to meeting demand without paying wages in quiet months. A definition or a list earns little credit."),
    mu('benefits', "Which are benefits to a business of employing part-time staff?",
      ['Staff can be scheduled to match busy times of the day', 'Wage costs are lower in quiet periods', 'Applicants who cannot work full-time can be attracted', 'Part-time staff never need any training', 'Part-time staff are always more committed than full-time staff'],
      [0, 1, 2],
      "Part-time staff give flexibility over hours, keep wage costs down when it is quiet and widen the pool of applicants. They still need training and are not always more committed."),
    mc('benefits', "What is a benefit to a business of offering a job share?",
      ['It can keep an experienced employee who no longer wants to work full-time', 'It means the business pays no wages for that role', 'It removes the need for any communication or handover between the two workers sharing it', 'It means the job is only filled during busy months'],
      "A job share lets a skilled employee reduce their hours instead of leaving, so the business keeps their experience. Two sharers also bring a wider range of skills."),
    mc('drawbacks', "What is a drawback for a business of a job share?",
      ['The two sharers must hand over work carefully, or tasks may be missed', 'The business has to pay double the wages for one job', 'Job share workers can only be employed during the summer', 'Job share workers are not legally allowed to receive any training from their employer'],
      "Two people doing one job need to communicate well. Without a clear handover, tasks can be duplicated or missed."),
    mc('drawbacks', "Why might an airline maintenance company choose not to use casual staff to repair its aircraft?",
      ['The work needs highly trained, experienced staff who know its procedures well, because safety is critical', 'Casual staff always cost more per hour than full-time staff, so the company would lose money on every repair job', 'Casual staff are not allowed by law to work in any engineering or maintenance business anywhere', 'Aircraft repairs are needed only once a year'],
      "Casual staff come and go, so they may not know the company's procedures. For safety-critical, skilled work, permanent trained staff give consistency and commitment."),
    mc('drawbacks', "What is a drawback of employing staff on permanent full-time contracts?",
      ['They must be paid even when the business is quiet', 'They have less experience than casual staff', 'They cannot be trained by the business', 'They are only allowed to work during the busy season each year'],
      "Full-time permanent staff give stability and commitment, but their wages are a cost every week, including in quiet periods when there is less work."),
    mc('drawbacks', "A theme park relies heavily on seasonal staff each summer. Which is the most likely problem?",
      ['New staff must be trained each year and may give poorer service at first', 'The park has to pay these staff for the whole year', 'The park cannot open during the summer months', 'Seasonal staff are not allowed to work in any customer-facing roles such as ticket sales'],
      "Seasonal staff change from year to year, so time and money go on training them, and service may suffer while they are learning."),
    mc('choose-type', "A petrol station is open from 6am to 11pm every day, with peaks at breakfast and early evening. Which type of employment best fits the work pattern?",
      ['A mix of full-time staff and part-time staff for the busy peaks', 'One full-time employee working all of the opening hours every day of the week', 'Only seasonal staff employed in the summer', 'Only casual staff with no regular hours'],
      "The long opening hours and daily peaks suit some full-time staff for cover plus part-time staff at the busy times, giving flexibility without paying for extra staff when it is quiet."),
    mc('choose-type', "Orla runs a fruit farm. She needs 30 pickers for six weeks at harvest, and 4 staff for the rest of the year. Which plan fits best?",
      ['Keep 4 permanent staff and hire seasonal pickers for the harvest', 'Employ 30 full-time staff on permanent contracts and pay them all year round', 'Use job shares for all 30 picking roles all year', 'Employ no permanent staff and use casual staff all year'],
      "Demand for workers rises only at harvest. Seasonal pickers meet that peak while permanent staff provide year-round skills, so the farm avoids paying 30 people for the quiet months."),
    mc('choose-type', "Halden Opticians needs an optometrist to cover for an employee on a year-long career break. Which type of contract is most suitable?",
      ['A temporary contract for the length of the absence', 'A casual contract with no regular hours, calling them in when needed', 'A seasonal contract for the summer only', 'A permanent full-time contract'],
      "The need lasts for a fixed period of one year, so a temporary contract fits. A permanent contract would leave the business with an extra optometrist when the employee returns."),
    mc('justify', "A cookery school runs classes only when enough people book. It is deciding whether to employ chefs full-time or to use casual chefs. Which factor would the decision most depend on?",
      ['How regular and predictable the bookings for classes are', 'The number of ovens the cookery school has in its kitchen', 'How many different recipes are taught in each cookery class', 'Whether the cookery school has its own website for bookings'],
      "If bookings are steady, full-time chefs give commitment and consistent quality. If bookings are irregular, casual chefs avoid paying wages when there are no classes."),
    mc('justify', "A student concludes: \"A hotel should employ only part-time staff because they are cheaper.\" What is the main weakness?",
      ['It ignores drawbacks such as lower commitment and the need for full-time cover of key roles', 'It is wrong because part-time staff are always paid more per hour', 'It is wrong because hotels cannot employ part-time staff', 'It is wrong because part-time means the job only lasts for a few months and then ends completely'],
      "A justified judgement weighs both sides. Part-time staff give flexibility, but the hotel may also need committed full-time staff for key roles such as managing the reception."),
    { skill: 'wage-cost', gen: function () {
      var pk = rint(2, 4), days = pick([5, 6]), full = pick([37, 38, 40]), rate = 10 + 0.5 * rint(0, 10);
      var ph = pk * days, ans = R.roundDp((full - ph) * rate, 2), biz = pick(['A sandwich bar', 'A city-centre caf&eacute;', 'A noodle bar', 'A bakery shop']);
      return { kind: 'num', q: biz + ' needs one extra server only during its ' + pk + '-hour lunch rush, ' + days + ' days a week. It could employ a full-time server for ' + full + ' hours a week, or a part-time server who works only the lunch rush. Both would be paid $' + money(rate) + ' an hour. How much does the business save each week by choosing the part-time server? Give your answer in $.',
        answer: ans, unit: '$', display: money(ans), tol: 0.005,
        why: 'The part-time server works ' + pk + ' &times; ' + days + ' = ' + ph + ' hours. Saving = (' + full + ' &minus; ' + ph + ') &times; $' + money(rate) + ' = $' + money(ans) + '. Part-time staff let the business pay only for the busy hours.' };
    } },
    { skill: 'wage-cost', gen: function () {
      var n = rint(3, 9), w = 50 * rint(28, 48), m = rint(2, 5);
      var ans = n * w * (12 - m), biz = pick(['An ice cream kiosk', 'A beach hotel', 'A garden centre', 'A boat tour company']);
      return { kind: 'num', q: biz + ' needs ' + n + ' extra staff for only ' + m + ' busy months each year. Each extra worker costs $' + commas(w) + ' a month. How much does it save each year by employing them as seasonal staff for ' + m + ' months instead of all 12 months? Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'The business avoids paying them for 12 &minus; ' + m + ' = ' + (12 - m) + ' months. Saving = ' + n + ' &times; $' + commas(w) + ' &times; ' + (12 - m) + ' = $' + commas(ans) + '.' };
    } },
    mc('wage-cost', "A full-time receptionist at a dental surgery asks to change her job into a job share with a colleague. Both are paid the same hourly rate. What is the most likely effect on the weekly wage cost of the role?",
      ['It stays about the same, as two sharers split one job\'s hours', 'It doubles, because two people are now paid for the job', 'It falls to zero, because job sharers are unpaid', 'It halves, because each sharer works only part of the week'],
      "A job share splits one full-time job's hours between two people, so the total hours paid, and the wage cost, stay about the same. The extra costs are smaller ones such as training two people and handover time."),
    mc('benefits', "Why might a hospital prefer full-time permanent nurses for its intensive care unit?",
      ['They build up experience of the unit\'s patients and procedures, giving consistent, safe care', 'They can be sent home without any pay whenever the unit is quiet, which keeps costs low for the hospital', 'They are paid only for the months when the hospital is busy', 'They never need to communicate with other nurses'],
      "Permanent full-time staff stay longer, gain experience and are committed, which matters when care must be consistent and safe.")
  ] };

  /* ------------------------------------------------------------------ */
  var DOCS = ['Job description', 'Person specification', 'Application form', 'Curriculum vitae (CV)'];
  B['BUS-S2-09'] = { title: 'Recruitment documents: job description to CV', items: [
    mc('identify-document', "Which recruitment document lists the title, tasks, duties and responsibilities of a job?",
      ['Job description', 'Person specification', 'Curriculum vitae (CV)', 'Application form'],
      "The job description is about the job itself: its title, tasks, duties and responsibilities."),
    mc('identify-document', "Which recruitment document lists the qualifications, skills, experience and personal qualities of the ideal candidate?",
      ['Person specification', 'Job description', 'Curriculum vitae (CV)', 'Application form'],
      "The person specification is about the person the business wants, not the duties of the job."),
    mc('identify-document', "Which recruitment document is written by the applicant to summarise their education, work experience and referees?",
      ['Curriculum vitae (CV)', 'Job description', 'Person specification', 'Application form'],
      "The applicant writes and updates their own CV. The business writes the job description and person specification and designs the application form."),
    mc('identify-document', "Which document is designed by the business but filled in by the applicant?",
      ['Application form', 'Curriculum vitae (CV)', 'Job description', 'Person specification'],
      "The business designs the application form so every applicant gives the same information in the same order; the applicant completes it."),
    mu('identify-document', "Which documents are written by the business, not the applicant?",
      ['Job description', 'Person specification', 'Curriculum vitae (CV)', 'A letter applying for the job'],
      [0, 1],
      "The business writes the job description and person specification to describe the job and the ideal person. The CV and the letter of application come from the applicant."),
    { skill: 'identify-document', gen: function () {
      var pool = [
        ['sets out that the role involves planning weekly delivery routes and supervising six drivers', 0],
        ['states that the post holder reports to the head of operations and manages the stock room', 0],
        ['says the ideal candidate holds a forklift licence and has two years\' warehouse experience', 1],
        ['lists "good communication skills" as essential and "a second language" as desirable', 1],
        ['asks every applicant the same questions in boxes, in the same order', 2],
        ['is supplied by the employer and completed by each applicant with their details', 2],
        ['is written by the applicant and lists their previous jobs and qualifications', 3],
        ['is prepared by the applicant and gives the names of two referees', 3]
      ];
      var t = pick(pool);
      var why = ['A job description describes the job: its tasks, duties, responsibilities and who the post holder reports to.',
        'A person specification describes the ideal person: qualifications, skills, experience and qualities, often split into essential and desirable.',
        'An application form is designed by the business and completed by applicants, so answers can be compared easily.',
        'A CV is written by the applicant and summarises their education, experience and referees.'][t[1]];
      return { kind: 'mcq', q: 'A recruitment document ' + t[0] + '. Which document is it?', options: DOCS.slice(), answer: t[1], why: why };
    } },
    mc('contents', "Which item would appear in the job description for a hotel receptionist?",
      ['Checking guests in and out and taking room bookings', 'At least two years of experience working in customer service', 'A list of the applicant\'s previous employers', 'The applicant\'s school qualifications'],
      "A job description lists the duties of the job. Required experience belongs in the person specification, and previous employers and qualifications appear on the CV or application form."),
    mc('contents', "Which item would appear in the person specification for a hotel receptionist?",
      ['Friendly manner and good spoken English', 'Answering the phone and taking room bookings', 'Working on the front desk from 7am to 3pm', 'Reporting to the front office manager'],
      "A person specification describes the qualities and skills of the ideal person. The other options describe the job's duties, hours and reporting line, which are in the job description."),
    mu('contents', "Which items would usually be included on an applicant's CV?",
      ['Qualifications gained', 'Previous jobs held', 'Contact details of referees', 'The duties of the advertised job', 'The salary range set by the employer'],
      [0, 1, 2],
      "A CV summarises the applicant's own history: qualifications, work experience and referees. The duties and salary of the job come from the business."),
    mu('contents', "Which items are most likely to be in the person specification for a pharmacist at Ridgeway Pharmacy?",
      ['A recognised pharmacy qualification', 'Accuracy and attention to detail', 'Dispensing medicines to customers', 'Ordering stock from suppliers', 'Opening the shop at 8am'],
      [0, 1],
      "Qualifications and personal qualities describe the ideal person, so they go in the person specification. Dispensing, ordering stock and opening times are duties of the job."),
    mc('contents', "Which of these would <b>not</b> appear in a job description?",
      ['The applicant\'s referees', 'The job title', 'The main duties of the job', 'Who the post holder reports to'],
      "Referees are given by the applicant on a CV or application form. A job description is written by the business about the job before anyone applies."),
    mc('contents', "A person specification for a chef lists \"food hygiene certificate: essential\". What does \"essential\" mean here?",
      ['Applicants without it are unlikely to be considered', 'It would be helpful but is not needed', 'The business will provide it once the successful applicant has started', 'It is a duty the chef will carry out each day'],
      "Essential criteria must be met to be considered for the job. Desirable criteria are useful extras that help the business choose between suitable applicants."),
    mc('purpose', "How does a job description help a business to recruit well?",
      ['Applicants understand what the job involves, so mainly suitable people apply', 'It tells the business the applicant\'s qualifications', 'It means the business does not need to interview anyone who applies for the job', 'It guarantees the person hired will never leave'],
      "When applicants know the real duties, people who are unsuited or uninterested are less likely to apply, saving the business time on unsuitable applications."),
    mc('purpose', "Why might a business ask applicants to complete an application form rather than send a CV?",
      ['Every applicant gives the same information in the same order, so they are easier to compare', 'Application forms are filled in by the business on behalf of each applicant, which saves applicants time', 'Application forms remove the need for a person specification', 'Application forms let applicants choose what to leave out'],
      "CVs come in many layouts and include different details. A standard form makes it easier and fairer to compare applicants against the person specification."),
    mc('purpose', "What is a drawback for a business of relying only on CVs?",
      ['CVs vary in layout and detail, so applicants are harder to compare fairly', 'CVs are written by the business for each applicant, which takes managers a lot of time', 'CVs never include any qualifications', 'CVs can only be used for internal recruitment'],
      "Each applicant chooses what to put in their CV and how, so the business may not find the same information for everyone."),
    mc('purpose', "Which statement correctly describes recruitment and selection?",
      ['Recruitment attracts people to apply; selection chooses between the applicants', 'Recruitment chooses between the applicants; selection attracts people to apply', 'Recruitment and selection both mean training new staff', 'Recruitment happens only after selection is complete'],
      "Recruitment is finding and attracting applicants. Selection comes afterwards and is choosing the best applicant for the job."),
    mc('chain', "A student is asked how a person specification helps a business hire the best employees. Which answer is the best developed?",
      ['It sets out the skills needed, so applicants can be compared against it, so the person hired can do the job well with less training.',
       'It is a document written by the business listing the qualifications, skills, experience and qualities of the ideal person for the job.',
       'It helps with recruitment, shortlisting, interviewing and many other tasks.',
       'It is written by the business and is very important for every vacancy.'],
      "The best answer says what the document contains, then how that helps compare applicants, then the result for the business. A definition or a list does not develop the point."),
    mc('chain', "Find the missing step. \"A clear job description lists the duties of a lab technician &rarr; ________ &rarr; fewer unsuitable people are hired and less time is wasted.\"",
      ['Applicants can judge whether they can do the work before applying', 'The business can lower the salary for the job', 'Applicants write the job description themselves', 'The business no longer needs to advertise the vacancy in newspapers'],
      "Knowing the duties lets applicants decide whether the job suits them, so the business receives better-matched applications and hires fewer unsuitable people."),
    mc('chain', "A student writes: \"The job description describes the ideal candidate's qualifications.\" What is wrong?",
      ['The job description describes the job; the person specification describes the ideal candidate', 'The job description is written by the applicant, not by the business, so it describes the applicant', 'The job description is only used after the person is hired', 'Nothing is wrong, the statement is correct'],
      "This is the most common mix-up. Job description = the job (duties); person specification = the person (qualifications, skills, qualities)."),
    mc('applied', "Crestline Juices needs a quality inspector for its bottling plant. Which item fits its person specification best?",
      ['Experience of food safety checks in a factory', 'Inspecting juice bottles for faults on the line', 'Working shifts from 6am to 2pm', 'Reporting to the production manager'],
      "Experience is a quality of the person, so it belongs in the person specification. Inspecting bottles, the shift times and the reporting line describe the job."),
    mc('applied', "Why does it help an applicant to keep their CV up to date?",
      ['They can apply quickly when a suitable vacancy appears, so they do not miss it', 'An up-to-date CV means they will not need to attend an interview for any job they apply for', 'An up-to-date CV replaces the job description', 'An up-to-date CV lets them set their own salary'],
      "An up-to-date CV is ready to send at once, so the applicant can apply before the closing date and show their latest experience."),
    mc('applied', "Which document would a business normally write first when a vacancy arises?",
      ['Job description, because the duties of the job must be decided before the ideal person is described', 'CV, because the business needs to know who will apply', 'Application form, because applicants must fill it in before the business decides what the job involves', 'Person specification, because the duties never need to be written down'],
      "The business first decides what the job involves (job description). It then uses those duties to decide what skills and qualities the ideal person needs (person specification).")
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-10'] = { title: 'Internal and external recruitment', items: [
    mc('classify', "A supermarket promotes one of its checkout supervisors to assistant store manager. What type of recruitment is this?",
      ['Internal recruitment', 'External recruitment', 'Induction training', 'Job rotation'],
      "The vacancy is filled by someone who already works for the business, so it is internal recruitment."),
    mc('classify', "A software company pays an agency to find it an experienced data analyst. What type of recruitment is this?",
      ['External recruitment', 'Internal recruitment', 'Off-the-job training', 'Job enrichment'],
      "An agency finds people from outside the business, so this is external recruitment."),
    { skill: 'classify', gen: function () {
      var internal = ['advertising the vacancy on the staff intranet for current employees', 'promoting an experienced team member to supervisor', 'inviting existing staff to apply through an email to all employees', 'moving a current employee from another branch into the role'];
      var external = ['placing an advert on a national jobs website', 'using a recruitment agency to find candidates', 'advertising in a specialist trade magazine', 'putting a job advert in the local newspaper', 'holding a stand at a university careers fair', 'posting the vacancy on the business\'s public social media page'];
      var biz = pick(['A logistics firm', 'A chain of gyms', 'An architecture practice', 'A restaurant group', 'A bus company']);
      var opts = [pick(internal)].concat(shuffled(external).slice(0, 3));
      return { kind: 'mcq', q: biz + ' has a vacancy. Which of these is internal recruitment?', options: opts, answer: 0,
        why: 'Internal recruitment fills the vacancy with someone who already works for the business. "' + opts[0] + '" only reaches existing staff; the other methods reach people outside the business.' };
    } },
    mc('internal-points', "Which is a benefit to a business of recruiting internally?",
      ['The person already knows how the business works, so less induction is needed', 'It brings in a much wider range of applicants with new ideas from other firms', 'It never leaves another vacancy to fill', 'It always costs more than recruiting externally'],
      "An existing employee knows the products, systems and people, so they settle in faster and need less induction. A wider pool and new ideas are benefits of external recruitment."),
    mc('internal-points', "Which is a drawback of internal recruitment?",
      ['It leaves another vacancy behind that must then be filled', 'It is usually slower and more expensive than advertising outside', 'The new person will not know anything about the business', 'The business must pay to advertise the job in national newspapers'],
      "When an employee is promoted, their old job becomes vacant, so the business has another post to fill. Paying for national adverts is a cost of external recruitment."),
    mu('internal-points', "Which are benefits of internal recruitment?",
      ['It is usually quicker and cheaper', 'Promotion chances can motivate staff', 'Managers already know the person\'s work record', 'It brings fresh ideas from other firms', 'It gives the widest choice of candidates'],
      [0, 1, 2],
      "Internal recruitment saves time and advertising costs, motivates staff who see a route to promotion and reduces risk because managers know the person. Fresh ideas and wide choice come from external recruitment."),
    mc('internal-points', "Why might relying only on internal recruitment harm a business over time?",
      ['Few new ideas and skills enter the business, so it may fall behind competitors', 'Staff will be demotivated because they can be promoted', 'Wage costs will fall to zero', 'The business will have far too many outside applicants to choose from for each job'],
      "If every post is filled from within, the business keeps the same ways of thinking and may miss skills and ideas that outsiders could bring."),
    mc('external-points', "Which is a benefit to a business of recruiting externally?",
      ['There is a larger pool of applicants, some with new skills and ideas', 'The person already knows the business\'s products and staff', 'It is always the quickest and cheapest way for a business to fill a vacancy', 'There is no need for any induction training'],
      "Advertising outside reaches far more people, so the business may find someone with skills it does not have and fresh ideas from elsewhere."),
    mu('external-points', "Which are drawbacks of external recruitment?",
      ['Advertising and interviewing take time and money', 'The new employee needs induction to learn how the business works', 'Existing staff may feel overlooked and become demotivated', 'It gives the business a wider choice of applicants', 'It leaves the promoted employee\'s old job vacant'],
      [0, 1, 2],
      "External recruitment costs time and money, needs induction and can upset staff who hoped for promotion. A wider choice is a benefit, and an empty old job is a drawback of internal recruitment."),
    mc('external-points', "Vela Cycles, a bike maker, appoints an outside candidate as head of design instead of promoting a senior designer. What is the most likely risk?",
      ['The senior designer may feel overlooked, become demotivated and leave', 'The new head of design will already know every Vela product', 'Vela will need to recruit a new senior designer straight away to replace the one promoted', 'Vela will save money on advertising and interviewing'],
      "When an outsider gets a post existing staff wanted, those staff may feel their work is not valued. Demotivated staff may work less hard or look for jobs elsewhere."),
    mc('advert', "Why should a job advertisement state how and by when to apply?",
      ['Suitable people know how to contact the business in time, so good applicants are not lost', 'It allows the business to avoid writing a job description or a person specification for the post', 'It means the business does not need to interview anyone', 'It guarantees every applicant will be suitable'],
      "Clear contact details and a closing date make it easy for suitable people to apply in time, so the business gets the applications it needs."),
    mc('advert', "Why might a business include the salary in a job advertisement?",
      ['People can decide if the pay suits them before applying, saving time for both sides', 'It means the business can legally pay less than the minimum wage for that job', 'It is the only information a job advert needs', 'It replaces the need for a person specification, because pay shows the skills needed'],
      "Showing the pay means people who would not accept it do not apply, so the business spends less time on applicants who would turn the job down."),
    mc('advert', "Which item is <b>least</b> likely to be needed in a job advertisement?",
      ['The business\'s full list of suppliers', 'The job title', 'The main duties and responsibilities of the job', 'How to apply'],
      "A job advert needs the job title, pay, main duties, required skills and how to apply. A list of suppliers does not help anyone decide whether to apply."),
    mc('advert', "Why might a fashion house advertise a vacancy on several websites and in a design magazine?",
      ['It reaches more people, giving access to a wider pool of skilled designers', 'It means existing staff can be promoted more easily into the design team instead', 'It removes the need to interview candidates', 'It lowers the cost of advertising to zero'],
      "Using several methods increases the number of suitable people who see the advert, so the business has more skilled applicants to choose from."),
    mc('advert', "Pellow Engineering needs a specialist in marine engines. Where would it be most sensible to advertise?",
      ['A trade magazine read by marine engineers', 'A poster in the staff canteen', 'A leaflet handed out in a local supermarket', 'A notice in the company\'s own reception'],
      "A specialist trade magazine is read by people who already have the skills needed, so the advert reaches suitable candidates. The other places reach staff or the general public."),
    mc('justify', "Nimbus Apps needs an expert in artificial intelligence. None of its current staff have these skills. Which conclusion is best justified?",
      ['Recruit externally: no one inside has the skills, even though advertising costs time and money', 'Recruit internally because it is always quicker and cheaper', 'Recruit internally so that no new ideas enter the business', 'Do not recruit at all, because external recruitment always demotivates all of the existing staff'],
      "A justified decision weighs the case. Internal recruitment is cheaper, but no one inside has the skills, so external recruitment is the only way to get the expertise, despite its cost."),
    mc('justify', "Harbour Foods needs a new store supervisor. Several experienced shop staff want promotion and know the store's systems well. Which conclusion is best justified?",
      ['Recruit internally: staff know the store and promotion motivates them, though another vacancy is left', 'Recruit externally, because outside candidates always bring new ideas and always perform better than existing staff', 'Recruit externally so that staff stop asking for promotion', 'Recruit internally because it never leaves any other vacancy'],
      "The case has suitable internal candidates who know the store, so internal recruitment is quicker, cheaper and motivating. The drawback, a new vacancy, is easier to fill at a lower level."),
    mc('justify', "Whether a business should recruit internally or externally for a manager's post will most depend on&hellip;",
      ['whether current employees have the skills and experience the post needs', 'how many applicants replied the last time the business advertised a job', 'whether the manager who is leaving was popular with the other members of staff', 'whether the post is advertised on a website or in a newspaper'],
      "If a suitable person already works there, internal recruitment is quicker and cheaper. If not, the business must look outside to get the right skills."),
    mc('justify', "A student writes: \"External recruitment is always better because it brings new ideas.\" What is the main weakness?",
      ['It does not weigh the cost, time and induction needed, or the effect on existing staff', 'It is wrong because external recruitment never brings any new ideas into a business at all', 'It is wrong because only internal recruitment brings new ideas', 'It is wrong because external recruitment is always free'],
      "The judgement is one-sided. New ideas are a real benefit, but a balanced answer weighs them against the extra cost, time, induction and possible demotivation of staff."),
    mc('chain', "Find the missing step. \"The business promotes from within &rarr; ________ &rarr; staff turnover falls.\"",
      ['Staff see a route to promotion and are motivated to stay', 'The business spends more on advertising vacancies outside', 'Staff have fewer chances to progress', 'Customers pay their bills more quickly'],
      "Seeing that promotion is possible motivates employees to stay with the business, which lowers staff turnover."),
    mu('chain', "A student writes: \"Recruiting externally gives a larger pool of applicants.\" Which two steps develop this point for a gym chain hiring a marketing manager?",
      ['so it may find someone with specialist marketing experience', 'who brings new ideas that help the gyms attract more members', 'so existing staff will definitely be promoted', 'which means the gym chain will not need to advertise', 'so induction training will not be needed'],
      [0, 1],
      "A larger pool makes it more likely to find a specialist, and that specialist's new ideas can help attract members. The other steps do not follow from the point."),
    mc('external-points', "What is a benefit of using a recruitment agency to fill a vacancy?",
      ['The agency finds and checks suitable candidates, saving the business time', 'The agency only offers the job to the business\'s existing staff', 'The agency service is always free, so the business saves money on every vacancy', 'The agency removes the need for any induction'],
      "An agency does much of the search for the business, which saves managers' time, although the business must pay the agency a fee.")
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-16'] = { title: 'Training: induction, on-the-job and off-the-job', items: [
    mc('classify', "A new mechanic at a bicycle repair shop learns how to adjust gears by watching and helping an experienced colleague. What type of training is this?",
      ['On-the-job training', 'Off-the-job training', 'Job rotation', 'External recruitment'],
      "Learning at the workplace while doing the job, for example by shadowing a colleague, is on-the-job training."),
    mc('classify', "An office worker spends one day a week at a local college studying for an accounting qualification. What type of training is this?",
      ['Off-the-job training', 'On-the-job training', 'Induction training', 'Job enrichment'],
      "The training takes place away from the normal workplace, at a college, so it is off-the-job training."),
    mc('classify', "On their first day, new staff at a warehouse are shown the fire exits, meet their team and learn the safety rules. What type of training is this?",
      ['Induction training', 'Off-the-job training', 'Job rotation', 'Promotion'],
      "Induction training introduces new employees to the workplace, their colleagues, the rules, and health and safety procedures."),
    mu('classify', "Which of these are examples of on-the-job training?",
      ['Shadowing an experienced colleague', 'A supervisor demonstrating a task at the workstation', 'Practising on the business\'s own till under guidance', 'A three-day course at a training centre', 'An evening class at a university'],
      [0, 1, 2],
      "On-the-job training happens at the workplace while working. Courses at a training centre or university are away from the workplace, so they are off-the-job."),
    mc('induction', "Which topic is most likely to be part of induction training?",
      ['Health and safety procedures in the workplace', 'An advanced professional qualification in management', 'Applying for a promotion', 'Writing a person specification'],
      "Every new starter needs to know the health and safety rules, so they are a core part of induction."),
    mc('induction', "Why does a business give induction training to new employees?",
      ['They settle in quickly, know the rules and become productive sooner', 'It means they will never need any further training', 'It replaces the need to recruit staff', 'It lets the business legally pay them less than its other, more experienced staff'],
      "Induction helps new staff understand the business, its people and its rules, so they can work safely and effectively sooner."),
    mc('induction', "Coralia Electronics sells televisions and sound systems in large stores. Which induction topic is most relevant for new sales staff?",
      ['How the store\'s main products work, so they can advise customers', 'How to calculate the business\'s annual profit', 'How to write a job advertisement for future vacancies in each of the stores', 'How to apply for a bank loan'],
      "Induction in context helps new staff do this job: knowing how the televisions and sound systems work means they can advise customers confidently."),
    mc('on-off', "What is a benefit of on-the-job training?",
      ['It is usually cheaper and uses the business\'s own equipment and methods', 'It always leads to a recognised national qualification for every member of staff', 'Staff learn new methods from outside experts', 'Staff are away from work and cannot be disturbed'],
      "On-the-job training costs little and is specific to the business, because staff learn on the actual equipment they will use."),
    mc('on-off', "What is a drawback of on-the-job training?",
      ['The experienced worker doing the training produces less, and bad habits may be passed on', 'Staff must travel to a college or training centre, which costs the business money and time', 'Course fees are usually very high', 'Staff never learn how the business does things'],
      "While an experienced employee is training someone, their own output falls. They may also pass on poor practices."),
    mc('on-off', "What is a benefit of off-the-job training?",
      ['Staff learn from specialist trainers and may gain new techniques or qualifications', 'It is always cheaper than on-the-job training', 'Staff keep working at their normal workstation', 'It is only used for new employees on their first day, to show them the safety rules'],
      "Off-the-job training uses outside experts, so staff can learn techniques the business does not yet use and may gain recognised qualifications."),
    mc('on-off', "What is a drawback of off-the-job training?",
      ['It costs fees and time, and staff are away from their work while training', 'It can only be given by an experienced colleague standing next to the trainee at work', 'It never teaches any new skills', 'It always takes place on the shop floor'],
      "Off-the-job training often involves course fees and travel, and output falls while staff are away from the workplace."),
    mc('on-off', "A café trains a new barista to use its own coffee machine. Why is on-the-job training the better choice here?",
      ['The skill is specific to the café\'s machine and can be shown cheaply during work', 'It gives the barista a university degree in catering and hospitality management', 'It takes the barista away from the café for several weeks to study at a college', 'It costs more than sending the barista on a course'],
      "The café's own machine and recipes are best learned in the café. A colleague can demonstrate them at low cost while the café keeps running."),
    mc('benefits-limits', "Asked for a drawback to an employer of training staff, which student answer is developed the furthest?",
      ['Staff who train others are taken away from their own work, so less is produced and productivity falls.',
       'Training is expensive, takes a lot of time, disrupts work and trained staff might leave afterwards for a rival.',
       'Training is when employees are taught the skills they need for their job.',
       'Training has some disadvantages, but it also has many advantages.'],
      "The best answer identifies one disadvantage (time) and develops it: staff are taken away from their work, so output and productivity fall. A list or a definition is not developed."),
    mu('benefits-limits', "Which are limitations of training for a business?",
      ['It costs money', 'Output may fall while staff are training', 'Trained staff may leave for a competitor', 'Staff become more skilled', 'Customer service may improve'],
      [0, 1, 2],
      "Training costs money, takes time away from work and the business may lose trained staff to rivals. Higher skills and better service are benefits, not limitations."),
    mc('benefits-limits', "Find the missing step. \"Staff at a phone repair shop are trained to fix more models &rarr; ________ &rarr; customers return and recommend the shop.\"",
      ['Repairs are done faster and right first time', 'The shop has to pay higher course fees', 'Staff spend more days away from the shop on training courses', 'The shop hires more managers'],
      "Training raises skills, so repairs are quicker and better. Good service makes customers come back and recommend the shop."),
    mc('benefits-limits', "Why might a business worry about paying for an expensive off-the-job qualification for an employee?",
      ['The employee may leave for a rival once qualified, so the business loses what it spent', 'Qualified employees always become less productive', 'The qualification will stop the employee from doing any work on the job while they study', 'Qualified employees cannot be promoted'],
      "A recognised qualification makes the employee more attractive to other employers. If they leave, the business has paid for training that a competitor now benefits from."),
    mc('benefits-limits', "How can training benefit the workers themselves, as well as the business?",
      ['They gain skills that can lead to promotion and higher pay', 'They no longer need to follow the health and safety rules at work', 'They will never need to be supervised again', 'They are guaranteed a job for life'],
      "New skills make workers more valuable, so they have better chances of promotion and higher pay, which can also motivate them."),
    mc('justify', "Larkfield Accountants wants its junior staff to gain professional accounting qualifications. Which conclusion is best justified?",
      ['Off-the-job training: a professional qualification needs specialist tutors, despite the time away', 'On-the-job training, because shadowing a colleague always leads to a professional accounting qualification', 'Induction training, because it covers professional qualifications', 'No training, because qualified staff never leave'],
      "Professional qualifications need specialist tutors and exams, which off-the-job courses provide. The cost and time away are drawbacks, but on-the-job training could not give the qualification."),
    mc('justify', "Whether a business chooses on-the-job or off-the-job training will most depend on&hellip;",
      ['whether the skill is specific to its own work or needs outside expertise', 'how many employees it has in each of its departments', 'whether its staff would like promotion to a management job in the next few years', 'whether it has recently recruited internally or externally'],
      "Skills specific to the business are learned cheaply on the job; skills needing specialist knowledge or a qualification are better learned off the job."),
    mc('justify', "A student says: \"On-the-job training means training that happens on an employee's first day.\" What is wrong?",
      ['That is induction; on-the-job training is learning at the workplace while doing the job', 'That describes off-the-job training, which happens at a college away from the workplace', 'That describes job rotation, which moves staff between jobs', 'Nothing is wrong, the statement is correct'],
      "Induction is for new starters. On-the-job training can happen at any time and means learning at the workplace while working."),
    { skill: 'benefits-limits', gen: function () {
      var n = rint(3, 12), fee = 50 * rint(4, 16), travel = 5 * rint(6, 24), lost = 10 * rint(10, 18);
      var ans = n * (fee + travel - lost), biz = pick(['A dental practice', 'A logistics firm', 'An IT support company', 'A hotel']);
      return { kind: 'num', q: biz + ' must train ' + n + ' employees to use new software. An off-the-job course costs $' + commas(fee) + ' per employee in fees plus $' + travel + ' per employee in travel. Instead, an experienced colleague could train them on the job, which costs $' + lost + ' per employee in the colleague\'s lost output. How much cheaper in total is on-the-job training? Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'Off-the-job cost per employee = $' + commas(fee) + ' + $' + travel + ' = $' + commas(fee + travel) + '. Saving per employee = $' + commas(fee + travel) + ' &minus; $' + lost + ' = $' + commas(fee + travel - lost) + '. Total = ' + n + ' &times; $' + commas(fee + travel - lost) + ' = $' + commas(ans) + '. On-the-job training is usually cheaper, though the colleague produces less while training.' };
    } },
    mc('induction', "A new nurse starts at a clinic without any induction. What is the most likely result?",
      ['She may not know the safety procedures, so mistakes and accidents are more likely', 'She will be more productive than the staff who had induction, because she starts work sooner', 'The clinic will save on all future training costs', 'She will automatically know where everything is kept'],
      "Without induction, a new employee may not know the rules, procedures or where things are, which leads to errors, slower work and safety risks.")
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-22'] = { title: 'Why motivating and keeping staff matters', items: [
    mc('key-terms', "What does retaining employees mean?",
      ['Keeping employees so that they do not leave the business', 'Recruiting new employees from outside', 'Paying employees only the minimum wage', 'Training employees so they can be promoted within the business'],
      "Retention is about keeping existing staff. Good retention means low staff turnover."),
    mc('key-terms', "What is staff turnover?",
      ['The rate at which employees leave and have to be replaced', 'The total value of sales made by staff', 'The number of hours each employee works', 'The movement of employees from one department of the business to another'],
      "Staff turnover measures how often employees leave. High turnover means the business keeps paying to recruit and train replacements."),
    mc('key-terms', "What is the minimum wage?",
      ['The lowest hourly rate of pay an employer is legally allowed to pay', 'The average hourly wage paid to all of the workers in a country each year', 'The pay a business gives to its managers', 'Extra pay given for reaching a target'],
      "The minimum wage is set by law; employers must pay at least this rate. Many businesses choose to pay more."),
    mc('key-terms', "What does productivity mean?",
      ['The amount of output produced by each worker in a given time', 'The total profit a business makes from all of its workers in a year', 'The number of employees in a business', 'The price customers pay for a product'],
      "Productivity measures how much each worker produces. Motivated staff usually work harder, so productivity rises."),
    mc('benefits', "Asked how a firm gains from having motivated workers, which student answer is developed the furthest?",
      ['Motivated staff are more likely to stay, so less is spent on recruiting and training, which lowers costs.',
       'Motivated staff work harder, are happier, take less time off, stay longer, make fewer mistakes and give better service.',
       'Motivation is the desire of employees to work hard and do a good job.',
       'Motivation is important for all businesses whatever their size.'],
      "The best answer names one benefit (retention) and develops it: fewer leavers, so less recruitment and training, so lower costs. A list or definition is not developed."),
    mc('benefits', "Find the missing step. \"Waiters at Saffron Grill are well motivated &rarr; ________ &rarr; customers return and revenue rises.\"",
      ['They give friendly, attentive service', 'The restaurant raises its menu prices', 'The restaurant hires more waiters', 'The chefs take more holidays'],
      "Motivated waiters give better service, and good service brings customers back, which raises revenue."),
    mu('benefits', "Which are benefits to a business of low staff turnover?",
      ['Lower recruitment and training costs', 'Experienced staff keep their product knowledge', 'Fewer disruptions while new staff learn', 'Higher spending on job adverts', 'More time spent interviewing'],
      [0, 1, 2],
      "When staff stay, the business spends less on replacing them, keeps their experience and avoids the disruption of new starters. More advertising and interviewing are signs of high turnover."),
    mc('benefits', "Demotivated staff at a parcel depot often take days off sick. What is the most likely effect on the business?",
      ['Parcels are delayed and the depot may have to pay for cover staff', 'Productivity at the depot rises', 'Recruitment costs fall to zero', 'Customers receive their parcels sooner because fewer staff are in the depot'],
      "High absence means less work gets done and cover may be needed, raising costs and delaying deliveries."),
    mc('benefits', "How can a well-motivated workforce help a business to attract new employees?",
      ['The business gains a reputation as a good employer, so more skilled people apply', 'It means the business no longer needs to advertise any of its vacancies outside the business', 'It means new employees can be paid below the minimum wage', 'It removes the need for a person specification'],
      "Happy, motivated staff speak well of their employer. A good reputation helps attract strong applicants."),
    mu('chains', "Brightloom Textiles employs skilled weavers. Which two steps form a chain showing why retaining them matters?",
      ['Experienced weavers make fewer faulty rolls of fabric', 'so less material is wasted and costs fall', 'so the business must advertise more often', 'which means weavers take more days off', 'so the business must cut its prices'],
      [0, 1],
      "Keeping experienced weavers means fewer faults, and fewer faults mean less waste and lower costs. The other steps do not follow from retaining skilled staff."),
    mc('chains', "A student writes: \"Motivated staff work harder.\" What is missing to turn this into a developed explanation?",
      ['The effect on the business, such as higher output and lower costs per item', 'A definition of motivation', 'A list of three more benefits, such as happier staff, better service and fewer absences', 'The name of a motivation theory'],
      "Saying staff work harder is only the first step. The answer must carry on to a business result, such as more output, lower unit costs or higher profit."),
    mc('chains', "A student is asked why motivation is important for a business. Which answer misreads the question?",
      ['The business should give staff a bonus and job rotation', 'Motivated staff stay longer, so recruitment costs fall', 'Motivated staff make fewer mistakes, so quality improves', 'Motivated staff give better service, so sales rise'],
      "Naming methods such as a bonus or job rotation answers \"how to motivate\", not \"why motivation matters\". The question needs a reason and its effect on the business."),
    mc('minimum-wage', "Kestrel Software pays its programmers well above the minimum wage. What is the most likely reason?",
      ['To attract skilled programmers and stop them moving to rival firms', 'Because the law requires all businesses to pay above the minimum wage', 'To reduce the number of applications it receives', 'Because programmers do not need any training'],
      "Skilled programmers are in demand. Higher pay attracts good applicants and makes them less likely to leave for a competitor."),
    mu('minimum-wage', "Which are valid reasons why a business might pay above the minimum wage?",
      ['To attract better-qualified applicants', 'To reduce staff turnover', 'To reward highly skilled work', 'Because the law forbids paying the minimum wage', 'To raise its total wage costs for no benefit'],
      [0, 1, 2],
      "Higher pay attracts and keeps good staff and rewards skill. Paying exactly the minimum wage is legal, and no business raises costs for no benefit."),
    mc('minimum-wage', "Palmyra Garden Centre pays its plant advisers above the minimum wage. Which reason is best in the context of this business?",
      ['Advisers stay longer, so their knowledge of plants is kept and they advise customers well', 'Advisers will need more training each year', 'The business will need to recruit new advisers more often, as higher pay attracts more applicants', 'Advisers will have less experience of gardening'],
      "In context, retaining advisers keeps their knowledge of plants and growing conditions, which helps them give good advice and make sales."),
    mc('minimum-wage', "Whether paying above the minimum wage increases a business's profit will most depend on&hellip;",
      ['whether the gains from higher productivity and lower turnover exceed the extra wage cost', 'whether its competitors also pay their staff above the legal minimum wage in the same country', 'how many hours each member of staff works per week', 'whether the extra pay is paid as a salary or as an hourly wage to staff'],
      "Higher pay is an extra cost. It raises profit only if the benefits, such as higher output, better service and lower recruitment costs, are worth more than the extra wages."),
    { skill: 'turnover-cost', gen: function () {
      var L = rint(6, 24), adv = 50 * rint(4, 12), intv = 50 * rint(3, 10), trn = 50 * rint(8, 30);
      var c = adv + intv + trn, ans = L * c, biz = pick(['A call centre', 'A chain of coffee shops', 'A delivery firm', 'A care home group']);
      return { kind: 'num', q: biz + ' had ' + L + ' employees leave last year. Replacing each one cost $' + commas(adv) + ' for advertising, $' + commas(intv) + ' for interviewing and $' + commas(trn) + ' for training. Calculate the total cost of replacing these employees. Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'Cost per leaver = $' + commas(adv) + ' + $' + commas(intv) + ' + $' + commas(trn) + ' = $' + commas(c) + '. Total = ' + L + ' &times; $' + commas(c) + ' = $' + commas(ans) + '. This is why retaining staff matters.' };
    } },
    { skill: 'turnover-cost', gen: function () {
      var L1 = rint(14, 30), L2 = rint(4, 12), c = 100 * rint(12, 45), ans = (L1 - L2) * c;
      var biz = pick(['A hotel', 'A supermarket', 'A cleaning company', 'A fitness club']);
      return { kind: 'num', q: biz + ' improved staff motivation, and the number of employees leaving each year fell from ' + L1 + ' to ' + L2 + '. Replacing each leaver costs $' + commas(c) + '. Calculate the yearly saving in replacement costs. Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'Fewer leavers = ' + L1 + ' &minus; ' + L2 + ' = ' + (L1 - L2) + '. Saving = ' + (L1 - L2) + ' &times; $' + commas(c) + ' = $' + commas(ans) + '.' };
    } },
    { skill: 'minimum-wage', gen: function () {
      var n = rint(5, 20), h = rint(25, 40), mw = 9 + 0.5 * rint(0, 6), extra = 0.5 * rint(1, 4);
      var pay = mw + extra, ans = R.roundDp(n * h * extra, 2);
      var biz = pick(['A garden centre', 'A bakery', 'A car wash', 'A hostel']);
      return { kind: 'num', q: 'The minimum wage is $' + money(mw) + ' an hour. ' + biz + ' pays its ' + n + ' staff $' + money(pay) + ' an hour instead. Each works ' + h + ' hours a week. How much extra does it pay each week compared with paying the minimum wage? Give your answer in $.',
        answer: ans, unit: '$', display: money(ans), tol: 0.005,
        why: 'Extra per hour = $' + money(pay) + ' &minus; $' + money(mw) + ' = $' + money(extra) + '. Extra each week = ' + n + ' &times; ' + h + ' &times; $' + money(extra) + ' = $' + money(ans) + '. The business pays this to attract and keep staff.' };
    } },
    mc('benefits', "Marlow Print is bringing in new digital printing machines. Why is it especially important to have motivated staff at this time?",
      ['Motivated staff are more willing to learn and accept new ways of working', 'Motivated staff will refuse to use the new machines', 'New machines mean the business will no longer need any print staff', 'Motivated staff always ask for lower pay'],
      "Change goes more smoothly when staff are motivated: they are more likely to accept training and new methods, so the investment pays off sooner."),
    mc('benefits', "Novak Opticians has a loyal team of staff who have worked there for many years. How does this most help the business?",
      ['Staff know the products and regular customers well, so their expert advice keeps customers returning', 'The business can stop paying its staff above the minimum wage', 'The business must spend more on recruitment every year because experienced staff expect promotion', 'Staff no longer need to follow the business\'s procedures'],
      "Experienced staff who stay build up product knowledge and relationships with customers. Their expert advice gives good service, which brings repeat sales."),
    mc('chains', "Which of these is a consequence of high staff turnover, not a cause of it?",
      ['Higher recruitment and training costs', 'Low pay compared with rival firms in the area', 'Poor working conditions', 'Little chance of promotion'],
      "Low pay, poor conditions and few promotion chances make staff leave (causes). The extra cost of replacing them is the result (consequence).")
  ] };

  /* ------------------------------------------------------------------ */
  B['BUS-S2-25'] = { title: 'Financial and non-financial methods of motivation', items: [
    mu('classify', "Which of these are financial methods of motivation?",
      ['Bonus', 'Commission', 'Fringe benefits', 'Job rotation', 'Autonomy'],
      [0, 1, 2],
      "Financial methods involve money or things with a money value: bonus, commission and fringe benefits. Job rotation and autonomy are non-financial."),
    mu('classify', "Which of these are non-financial methods of motivation?",
      ['Job enrichment', 'Job rotation', 'Autonomy', 'Promotion', 'Remuneration'],
      [0, 1, 2],
      "Job enrichment, job rotation and autonomy change the job itself without extra money. Promotion brings higher pay and remuneration is pay, so both are financial."),
    mc('classify', "A cinema chain gives its staff free film tickets and discounts on snacks. How are these classified?",
      ['Fringe benefits, a financial method', 'Job enrichment, a non-financial method', 'Autonomy, a non-financial method', 'Commission, a financial method'],
      "Fringe benefits are extras on top of normal pay, such as discounts and free products. They have a money value, so they are a financial method."),
    { skill: 'classify', gen: function () {
      var fin = [['a bonus for meeting the monthly target', 'bonus'], ['commission on every policy sold', 'commission'], ['a staff discount on all products', 'fringe benefit'], ['free private health insurance', 'fringe benefit'], ['promotion to team leader with higher pay', 'promotion']];
      var non = ['moving between the bakery, deli and checkout every few weeks', 'being given responsibility for planning a whole project', 'choosing how to organise their own working day', 'taking on more challenging tasks such as training new staff'];
      var wantFin = Math.random() < 0.5, opts, why;
      if (wantFin) {
        var f = pick(fin); opts = [f[0]].concat(shuffled(non).slice(0, 3));
        why = '"' + f[0] + '" is a ' + f[1] + ', which involves money or something with a money value, so it is financial. The others change the job itself, so they are non-financial.';
        return { kind: 'mcq', q: 'Which of these is a <b>financial</b> method of motivation?', options: opts, answer: 0, why: why };
      }
      var n = pick(non), fs = shuffled(fin).slice(0, 3).map(function (x) { return x[0]; });
      opts = [n].concat(fs);
      why = '"' + n + '" changes the job or gives freedom without extra money, so it is non-financial. The others are pay, rewards or benefits with a money value.';
      return { kind: 'mcq', q: 'Which of these is a <b>non-financial</b> method of motivation?', options: opts, answer: 0, why: why };
    } },
    mc('define', "What is commission?",
      ['Pay linked to the number or value of sales an employee makes', 'A fixed extra payment for good attendance', 'Moving an employee to a more senior job', 'Freedom for workers to decide how and when to do their own work'],
      "Commission rises with sales, so it encourages sales staff to sell more."),
    mc('define', "What is a bonus?",
      ['An extra payment on top of basic pay, for example for reaching a target', 'Pay that depends only on the value of each sale', 'A non-financial reward such as praise', 'A move between different jobs in the business to reduce boredom at work'],
      "A bonus is added to basic pay, often when a target is met. Commission is linked directly to the sales an individual makes."),
    mc('define', "What is job rotation?",
      ['Employees move between different jobs or tasks for periods of time', 'Employees are given more challenging tasks and more responsibility at work', 'Employees decide for themselves how to do their work', 'Employees receive extra pay for reaching a target'],
      "Job rotation moves staff between tasks to reduce boredom. Giving more challenging tasks is job enrichment, and freedom to decide is autonomy."),
    mc('define', "What is job enrichment?",
      ['Giving employees more challenging tasks and responsibility', 'Moving employees between different jobs of a similar level of difficulty', 'Paying employees for each item they sell', 'Giving employees a company car'],
      "Job enrichment makes the job more interesting and demanding, for example by adding planning or decision-making, rather than just moving staff around."),
    mc('define', "What is autonomy at work?",
      ['Freedom for employees to decide how they do their own work', 'Pay set by the government as the lowest legal rate for all workers', 'A move to a higher job with more pay', 'A discount on the business\'s products'],
      "Autonomy means trusting workers to make decisions about their own work, which can make them feel valued and responsible."),
    mc('define', "What does remuneration mean?",
      ['The pay an employee receives for their work', 'The freedom to choose how to work', 'Training given away from the workplace at a college', 'Moving between departments'],
      "Remuneration is the reward for work, such as a wage or salary. It is the basic financial method of motivation."),
    mc('apply', "Brisa Motors sells new cars. Which method would most directly encourage its sales staff to sell more cars?",
      ['Commission on each car sold', 'Job rotation between departments', 'A free staff canteen', 'Autonomy over cleaning the showroom'],
      "Commission links pay to sales, so each extra car sold raises the salesperson's pay. This gives a direct incentive to sell more."),
    mc('apply', "Workers on a bottling line do the same simple task all day and say they are bored. Which method best tackles this problem?",
      ['Job rotation between tasks on the line', 'Commission on sales made', 'A company car for each worker', 'Paying all line workers exactly the minimum wage'],
      "Job rotation gives variety by moving workers between tasks, which reduces boredom. Commission does not suit line workers who do not sell."),
    mc('apply', "Selin is an experienced graphic designer who wants more challenge. Which method best suits her?",
      ['Job enrichment, such as leading a new client project', 'Job rotation so she spends some weeks on the reception desk', 'Commission on each product sold', 'A shorter lunch break'],
      "Job enrichment adds responsibility and challenge, which suits an experienced employee who wants to develop. Rotating her to reception would not use her skills."),
    mc('apply', "Which fringe benefit best fits a chain of sports shops?",
      ['A staff discount on sports clothing and equipment', 'Commission paid on every sale that is made by the other branches', 'Job rotation between the shops', 'More freedom to set store prices'],
      "A staff discount on the shop's own products is a fringe benefit that fits the business and is valued by staff who like sport."),
    mc('effects', "Asked how giving staff fringe benefits affects a firm, which student answer is developed the furthest?",
      ['Staff value the benefits and are less likely to leave, so turnover and recruitment costs fall.',
       'Fringe benefits include company cars, staff discounts, free meals, gym membership and private health insurance.',
       'Fringe benefits are extras given to staff on top of their normal pay.',
       'Fringe benefits are popular with staff, managers and customers.'],
      "The best answer gives one impact and develops it: staff stay, turnover falls, recruitment costs fall. Examples or a definition alone do not explain an impact."),
    mc('effects', "What is a drawback of paying sales staff mainly by commission?",
      ['Staff may pressure customers into buying, which can harm the business\'s reputation', 'Staff have no reason to make any sales at all', 'Commission is a non-financial method of motivation', 'Commission costs the business exactly the same amount whatever the value of sales'],
      "Because pay depends on sales, some staff may push customers too hard or ignore after-sales service. Their income may also be unstable."),
    mc('effects', "What is a drawback of job rotation for a business?",
      ['Staff must be trained for several tasks, which costs time and money', 'It always raises the wage bill a lot', 'It gives staff extra pay for every different task they learn to do on the line', 'It means staff never change tasks'],
      "Workers need training for each new task, and they may be slower while they learn, so output can fall at first."),
    mc('effects', "What is a drawback of giving employees more autonomy?",
      ['Some staff may not want the responsibility, and unsupervised mistakes may be made', 'It always costs more than paying a bonus', 'It stops staff making any decisions', 'It is a financial method that always raises the wage costs of the business a lot'],
      "Autonomy suits confident, skilled staff. Others may feel stressed by the responsibility, and poor decisions may go unnoticed."),
    mc('effects', "Why might the motivating effect of a one-off bonus not last?",
      ['Once it is paid, staff may expect another, and effort may fall back without it', 'A bonus is a non-financial method, so it has no money value for the employee at all', 'A bonus always lowers staff morale immediately', 'A bonus cannot be linked to any target'],
      "Money can raise effort quickly, but the effect may fade once the reward has been paid, and it adds cost each time."),
    mc('justify', "A student concludes: \"The business should pay every employee a bonus because money motivates everyone.\" What is the main weakness?",
      ['It ignores the cost and that some staff value challenge or responsibility more than money', 'It is wrong because bonuses are a non-financial method', 'It is wrong because bonuses are illegal', 'It is wrong because no employees are motivated by money, only by interesting and challenging work'],
      "A balanced judgement weighs the cost and suitability of a method. Some staff are motivated more by interesting work or responsibility, which non-financial methods provide at lower cost."),
    mc('justify', "Which factor would most affect whether a business uses commission or job enrichment to motivate staff?",
      ['The type of job, for example whether staff sell to customers', 'Whether the business is a sole trader, partnership or limited company', 'How many shareholders the business has and the dividends they expect', 'Whether the business pays its suppliers in cash or on credit'],
      "Commission only makes sense where staff make sales. For roles without sales, non-financial methods such as enrichment may motivate better."),
    { skill: 'pay-calc', gen: function () {
      var basic = 100 * rint(9, 20), c = pick([2, 3, 4, 5, 8, 10]), sales = 1000 * rint(12, 60);
      var com = sales * c / 100, ans = basic + com, job = pick(['A car salesperson', 'An estate agent', 'A mobile phone sales adviser', 'A furniture sales assistant']);
      return { kind: 'num', q: job + ' earns a basic pay of $' + commas(basic) + ' a month plus ' + c + '% commission on the value of their sales. This month their sales were worth $' + commas(sales) + '. Calculate their total pay for the month. Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'Commission = ' + c + '% &times; $' + commas(sales) + ' = $' + commas(com) + '. Total pay = $' + commas(basic) + ' + $' + commas(com) + ' = $' + commas(ans) + '.' };
    } },
    { skill: 'pay-calc', gen: function () {
      var basic = 100 * rint(12, 25), bonus = 50 * rint(3, 10), T = 10 * rint(30, 60);
      var met = Math.random() < 0.5, P = met ? T + 5 * rint(0, 12) : T - 5 * rint(1, 10);
      var ans = basic + (met ? bonus : 0);
      return { kind: 'num', q: 'A factory worker earns $' + commas(basic) + ' a month. A bonus of $' + commas(bonus) + ' is added if they pack at least ' + T + ' boxes in the month. This month they packed ' + P + ' boxes. Calculate their total pay for the month. Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: met ? P + ' boxes is at least the target of ' + T + ', so the bonus is paid: $' + commas(basic) + ' + $' + commas(bonus) + ' = $' + commas(ans) + '.'
                 : P + ' boxes is below the target of ' + T + ', so no bonus is paid. Total pay is the basic $' + commas(basic) + '.' };
    } },
    { skill: 'pay-calc', gen: function () {
      var n = rint(12, 60), m = 5 * rint(5, 14), ans = n * m * 12;
      var biz = pick(['A software company', 'An insurance firm', 'A design agency', 'A hotel group']);
      return { kind: 'num', q: biz + ' offers free gym membership to its ' + n + ' employees as a fringe benefit. Membership costs the business $' + m + ' per employee each month. Calculate the yearly cost of this fringe benefit. Give your answer in $.',
        answer: ans, unit: '$', display: commas(ans),
        why: 'Yearly cost = ' + n + ' employees &times; $' + m + ' &times; 12 months = $' + commas(ans) + '. This cost must be weighed against benefits such as lower staff turnover.' };
    } },
    mc('apply', "How does promotion motivate employees?",
      ['It brings higher pay and status, rewards good work and gives staff a goal', 'It moves staff to a different job at the same level to reduce boredom and repetition', 'It gives staff a discount on products', 'It lets staff decide how to organise their work'],
      "Promotion is a financial method because the higher job brings higher pay. It also gives status and a goal to work towards.")
  ] };
})();
